script:
frappe.ui.form.on("Stock Entry", {
	custom_vending_machine(frm) {
		if (!frm.doc.custom_vending_machine) {
			return;
		}
		frappe.call({
			method: "vending_tracker.api.machine.get_machine_warehouse",
			args: { machine: frm.doc.custom_vending_machine },
			callback(r) {
				if (!r.message) {
					return;
				}
				frm.set_value("custom_is_vending_transaction", 1);
				if (["Material Receipt", "Material Transfer"].includes(frm.doc.stock_entry_type)) {
					frm.set_value("to_warehouse", r.message);
				} else if (frm.doc.stock_entry_type === "Material Issue") {
					frm.set_value("from_warehouse", r.message);
				}
				frm.refresh_field("to_warehouse");
				frm.refresh_field("from_warehouse");
			},
		});
	},
	refresh(frm) {
		if (frm.doc.custom_is_vending_transaction) {
			frm.set_headline(__("Vending Restock Transaction"));
		}
	},
});

frappe.ui.form.on("Vending Machine", {
	refresh(frm) {
		if (frm.is_new()) {
			return;
		}
		frappe.call({
			method: "vending_tracker.api.machine.get_machine_summary",
			args: { machine: frm.doc.name },
			callback(r) {
				if (!r.message) {
					return;
				}
				const parts = [];
				if (r.message.low_stock_count > 0) {
					parts.push(__("{0} low stock slot(s)", [r.message.low_stock_count]));
				}
				if (r.message.is_online) {
					parts.push(__("Online"));
				} else {
					parts.push(__("Offline"));
				}
				if (parts.length) {
					frm.set_headline(parts.join(" · "));
				}
			},
		});
	},
});
